import React, { useState } from "react";
import axios from "axios";
import "./dashboard.css";

function MaterialsStudent() {
  const [subjectCode, setSubjectCode] = useState("");
  const [materials, setMaterials] = useState([]);

  const loadMaterials = async () => {
    const res = await axios.get(
      `http://127.0.0.1:8000/materials/${subjectCode}`
    );

    setMaterials(res.data.materials || []);
  };

  return (
    <div>
      <h2>📚 Study Materials</h2>

      <input
        className="input"
        placeholder="Enter Subject Code"
        value={subjectCode}
        onChange={(e) => setSubjectCode(e.target.value)}
      />

      <button className="btn btn-primary" onClick={loadMaterials}>
        Load
      </button>

      {materials.map(m => (
        <div className="list-card" key={m.id}>
          <h4>{m.title}</h4>

          {m.file_url.endsWith(".mp4") ? (
            <video controls width="300"
              src={`http://127.0.0.1:8000/${m.file_url}`} />
          ) : (
            <img width="300"
              src={`http://127.0.0.1:8000/${m.file_url}`} />
          )}
        </div>
      ))}
    </div>
  );
}

export default MaterialsStudent;
